// 半仿真：用键盘模拟车门状态周期上报
variables {
  msTimer doorTimer;
}

on key 's' {
  setTimer(doorTimer, 1000);   // 按 s 启动 1s 周期定时器
}

on timer doorTimer {
  message DoorState doormsg;
  doormsg.Door_L = 1;           // 左门开
  doormsg.Door_R = 1;           // 右门开
  output(doormsg);              // 发送到总线
  setTimer(doorTimer, 1000);    // 必须复位定时器才能循环
}

testcase CheckEngineSpeedRange() {
  TestCaseDescription("引擎转速应在 0~8000 rpm 内");
  @Engine::EngineSpeedEntry = 6500;
  testWaitForTimeout(200);              // 等待信号稳定
  if (@Engine::EngineSpeedDspMeter > 8000)
    TestStepFail("转速超上限");
  else
    TestStepPass("转速在合理范围");
}
